practice.solution:
def track_memory(ops):
    used = {}
    for op in ops:
        p = op.split()
        if p[0] == 'alloc':
            used[p[1]] = int(p[2])
        elif p[0] == 'free':
            used.pop(p[1], None)
    return [[k, used[k]] for k in sorted(used)]

