practice.solution:
NEXT = {
    ('new', 'admit'): 'ready',
    ('ready', 'dispatch'): 'running',
    ('running', 'timeout'): 'ready',
    ('running', 'wait'): 'waiting',
    ('waiting', 'io_done'): 'ready',
    ('running', 'exit'): 'terminated',
}

def run_events(events):
    state = 'new'
    seen = []
    for i, e in enumerate(events):
        if (state, e) not in NEXT:
            return 'error at ' + str(i)
        state = NEXT[(state, e)]
        seen.append(state)
    return seen

