practice.solution:
def interleave(schedule):
    counter = 0
    reg = {'A': 0, 'B': 0}
    step = {'A': 0, 'B': 0}
    for t in schedule:
        s = step[t]
        if s == 0:
            reg[t] = counter
        elif s == 1:
            reg[t] = reg[t] + 1
        elif s == 2:
            counter = reg[t]
        step[t] = s + 1
    return counter

