def allocate(holes, size, strategy):
    # your code
    pass

practice.solution:
def allocate(holes, size, strategy):
    fit = [i for i in range(len(holes)) if holes[i] >= size]
    if not fit:
        return -1
    if strategy == 'first':
        return fit[0]
    if strategy == 'best':
        return min(fit, key=lambda i: (holes[i], i))
    return min(fit, key=lambda i: (-holes[i], i))

