    # your code
    pass

practice.solution:
def page_faults(ref, frames, algo):
    mem = []
    faults = 0
    for i, p in enumerate(ref):
        if p in mem:
            if algo == 'lru':
                mem.remove(p)
                mem.append(p)
            continue
        faults += 1
        if len(mem) >= frames:
            if algo == 'opt':
                def nxt(q):
                    for j in range(i + 1, len(ref)):
                        if ref[j] == q:
                            return j
                    return 10 ** 9
                victim = max(mem, key=nxt)
                mem.remove(victim)
            else:
                mem.pop(0)
        mem.append(p)
    return faults

