practice.solution:
def buffer_run(capacity, ops):
    count = 0
    dropped = 0
    for op in ops:
        if op == 'P':
            if count < capacity:
                count += 1
            else:
                dropped += 1
        else:
            if count > 0:
                count -= 1
            else:
                dropped += 1
    return [count, dropped]

