practice.solution:
def alloc_contiguous(disk, n):
    run = 0
    for i in range(len(disk)):
        if disk[i] == 0:
            run += 1
            if run == n:
                start = i - n + 1
                for j in range(start, i + 1):
                    disk[j] = 1
                return start
        else:
            run = 0
    return -1

